"""Exact retained PBT HTML candidate; no database writes or canonical acceptance."""
import hashlib
import json
import re
from decimal import Decimal
from html.parser import HTMLParser

SOURCE_SHA256 = 'b9a804fd92f10c02692db9afe52ba11626ca19b5f57e54dba5efe62d5bdac788'
SOURCE_BYTES = 654131
ROWS = {7: (4,5,6,8,9,10,11,12), 8: (3,4,5,6,7,8),
        9: (3,4,5,6,7,8), 10: (3,4,5,6,7),
        13: (6,7,8,9,12,13,14,16,17,18,19,20,21)}

def sha(value):
    return hashlib.sha256(value.encode('utf-8')).hexdigest()

def compact(value):
    return ' '.join(value.split())

class Tables(HTMLParser):
    def __init__(self, source):
        super().__init__(convert_charrefs=True)
        self.source = source
        self.offsets = [0]
        for line in source.splitlines(keepends=True):
            self.offsets.append(self.offsets[-1] + len(line))
        self.tables = []
        self.depth = 0
        self.row = None
        self.cell = None
        self.feed(source)
        self.close()
        if self.depth or self.cell is not None:
            raise ValueError('UNTERMINATED_TABLE_OR_CELL')

    def source_offset(self):
        line, col = self.getpos()
        return self.offsets[line-1] + col

    def handle_starttag(self, tag, attrs):
        if tag == 'table':
            if self.depth:
                raise ValueError('NESTED_TABLE_UNSUPPORTED')
            self.depth = 1
            self.tables.append([])
        elif self.depth and tag == 'tr':
            if self.row is not None:
                raise ValueError('UNCLOSED_ROW')
            self.row = []
            self.tables[-1].append(self.row)
        elif self.depth and tag in ('td', 'th'):
            if self.row is None or self.cell is not None:
                raise ValueError('CELL_STRUCTURE')
            self.cell = {'text': [], 'start': self.source_offset()}
        elif self.cell is not None and tag == 'br':
            self.cell['text'].append(' ')

    def handle_data(self, data):
        if self.cell is not None:
            self.cell['text'].append(data)

    def handle_endtag(self, tag):
        if self.depth and tag in ('td', 'th'):
            if self.cell is None:
                raise ValueError('CELL_CLOSE_WITHOUT_OPEN')
            end = self.source.find('>', self.source_offset()) + 1
            raw = self.source[self.cell['start']:end]
            self.row.append({'text':compact(''.join(self.cell['text'])),
                             'raw_html':raw, 'raw_html_sha256':sha(raw),
                             'source_character_start':self.cell['start'],
                             'source_character_end_exclusive':end})
            self.cell = None
        elif self.depth and tag == 'tr':
            if self.cell is not None:
                raise ValueError('UNCLOSED_CELL')
            self.row = None
        elif tag == 'table':
            if self.row is not None or self.cell is not None:
                raise ValueError('UNCLOSED_ROW_OR_CELL')
            self.depth = 0

def number(token, suffix='', percent=False):
    token, suffix = compact(token), compact(suffix)
    if token in ('—','–','-') and not suffix:
        return None, 'NULL_DASH'
    if percent:
        if suffix != '%':
            raise ValueError('PERCENT_SUFFIX_REQUIRED')
    elif suffix not in ('', ')'):
        raise ValueError('UNSUPPORTED_SUFFIX')
    neg = token.startswith('(')
    if neg != (suffix == ')'):
        raise ValueError('UNBALANCED_PARENTHESES')
    value = token[1:] if neg else token
    if not re.fullmatch(r'(?:0|[1-9][0-9]*|[1-9][0-9]{0,2}(?:,[0-9]{3})+)(?:\.[0-9]+)?', value):
        raise ValueError('UNSUPPORTED_NUMERIC_LEXEME')
    n = Decimal(value.replace(',', ''))
    if neg:
        n = -n
    return format(n, 'f'), 'NUMERIC'

def extract(source):
    if len(source.encode('utf-8')) != SOURCE_BYTES or sha(source) != SOURCE_SHA256:
        raise ValueError('EXACT_SOURCE_PIN_REQUIRED')
    tables = Tables(source).tables
    if len(tables) != 15:
        raise ValueError('TABLE_COUNT_CHANGED')
    facts = []
    for table_no, row_numbers in ROWS.items():
        for row_no in row_numbers:
            cells = tables[table_no-1][row_no-1]
            indices = (2,5) if table_no == 10 else ((3,7,11,15) if table_no == 13 else (3,7))
            if len(cells) != (7 if table_no == 10 else (17 if table_no == 13 else 9)):
                raise ValueError('CELL_COUNT_CHANGED')
            for ci, index in enumerate(indices):
                percent = table_no == 13 and row_no == 20
                value, state = number(cells[index]['text'], cells[index+1]['text'], percent)
                if cells[index-1]['text'] not in ('', '$'):
                    raise ValueError('CURRENCY_PREFIX_CHANGED')
                year = 2026 if ci < (2 if table_no == 13 else 1) else 2025
                period_start = f'{year}-01-01'
                period_end = f'{year}-03-31'
                period_kind = 'DURATION'
                period_boundary = None
                dimension = None
                if table_no == 7:
                    period_kind, period_start = 'INSTANT', None
                    period_end = '2026-03-31' if ci == 0 else '2025-12-31'
                elif table_no == 9 and row_no in (3,7):
                    period_kind, period_start = 'INSTANT', None
                    period_boundary = 'OPENING_OF_REPORTED_QUARTER' if row_no == 3 else 'CLOSING_OF_REPORTED_QUARTER'
                    # Opening date is the derived quarter boundary, not an explicit
                    # separately printed prior-year balance-sheet date.
                    period_end = f'{year}-01-01' if row_no == 3 else f'{year}-03-31'
                elif table_no == 10:
                    dimension = ('UNDERLYING_PROPERTIES','NET_TO_TRUST')[ci]
                    period_start = '2026-01-01' if row_no == 4 else None
                    period_end = '2025-12-31' if row_no == 3 else '2026-03-31'
                    period_kind = 'DURATION' if row_no == 4 else 'INSTANT'
                elif table_no == 13:
                    dimension = ('WADDELL_RANCH','TEXAS_ROYALTY')[ci % 2]
                unit = 'percent' if percent else ('USD/beneficial_unit' if table_no in (8,9) and row_no == 8 else 'USD')
                facts.append({'table_ordinal':table_no,'row_ordinal':row_no,
                    'value_cell_ordinal':index+1,'column_ordinal':ci+1,
                    'label':cells[0]['text'],'source_value':cells[index]['text'],
                    'source_suffix':cells[index+1]['text'],'value':value,'state':state,
                    'unit':unit,'scale':0,'period_kind':period_kind,
                    'period_start':period_start,'period_end':period_end,
                    'period_boundary':period_boundary,
                    'period_date_basis':'DERIVED_REPORTED_QUARTER_BOUNDARY' if period_boundary else 'REPORTED_TABLE_HEADER_OR_ROW',
                    'property_scope':dimension,'value_cell':cells[index],
                    'suffix_cell':cells[index+1], 'source_body_sha256':SOURCE_SHA256,
                    'canonical_qualified':False})
    return {'version':'PBT_PINNED_HTML_CANDIDATE_V1','source_sha256':SOURCE_SHA256,
        'source_bytes':SOURCE_BYTES,'accounting_basis':'MODIFIED_CASH_NON_GAAP_ROYALTY_TRUST',
        'source_role':'PRE_AUGUST_BASELINE_SUPPORT','facts':facts,
        'holds':['CANONICAL_METRIC_MAPPING_UNREVIEWED','TRUST_UNIT_NOT_COMMON_SHARE_SUBSTITUTION',
                 'TABLE8_TABLE9_DISTRIBUTABLE_INCOME_DIFFERENCE_PRESERVED',
                 'EARLIEST_EARNINGS_PUBLICATION_NOT_ESTABLISHED','HISTORICAL_IDENTITY_AND_FAMILY_UNACCEPTED'],
        'family_accepted':False,'production_integrated':False}

if __name__ == '__main__':
    import sys
    source = json.load(open(sys.argv[1], encoding='utf-8'))['body']
    with open(sys.argv[2], 'w', encoding='utf-8') as target:
        json.dump(extract(source), target, sort_keys=True, separators=(',',':'), ensure_ascii=False)
        target.write('\n')

