"""Bounded exact-source and parser boundary checks; no production acceptance."""
import json
import unittest
from decimal import Decimal
from pathlib import Path
from extract_pbt import extract, number, Tables, sha, SOURCE_SHA256

class PBTChecks(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.body=json.loads(Path(__file__).with_name('private_source.json').read_text())['body']
        cls.output=extract(cls.body)
        cls.facts=cls.output['facts']
        cls.values={(x['table_ordinal'],x['row_ordinal'],x['column_ordinal']):
                    None if x['value'] is None else Decimal(x['value']) for x in cls.facts}

    def test_population_and_nulls(self):
        self.assertEqual(len(self.facts),102)
        self.assertEqual(sum(x['value'] is None for x in self.facts),8)
        self.assertEqual(sum(x['unit']=='percent' for x in self.facts),4)
        self.assertEqual(sum(x['unit']=='USD/beneficial_unit' for x in self.facts),4)

    def test_all_source_cell_offsets_and_hashes(self):
        for fact in self.facts:
            for key in ('value_cell','suffix_cell'):
                cell=fact[key]
                self.assertEqual(self.body[cell['source_character_start']:cell['source_character_end_exclusive']],cell['raw_html'])
                self.assertEqual(sha(cell['raw_html']),cell['raw_html_sha256'])

    def test_independent_html_parser_all_selected_cells(self):
        from lxml import html
        tables=html.fromstring(self.body).xpath('//table')
        for fact in self.facts:
            rows=tables[fact['table_ordinal']-1].xpath('./tr|./tbody/tr')
            cells=rows[fact['row_ordinal']-1].xpath('./td|./th')
            for shift,field in ((0,'source_value'),(1,'source_suffix')):
                value=' '.join(' '.join(cells[fact['value_cell_ordinal']-1+shift].itertext()).split())
                self.assertEqual(value,fact[field])

    def test_balance_sheet_equations_both_dates(self):
        v=self.values
        for c in (1,2):
            self.assertEqual(v[7,4,c]+v[7,5,c],v[7,6,c])
            self.assertEqual(v[7,8,c]+v[7,9,c],v[7,10,c])
            self.assertEqual(v[7,10,c]+v[7,11,c],v[7,12,c])
            self.assertEqual(v[7,6,c],v[7,12,c])

    def test_distributable_income_and_trust_rollforward(self):
        v=self.values
        for c in (1,2):
            self.assertEqual(v[8,3,c]+v[8,4,c],v[8,5,c])
            self.assertEqual(v[8,5,c]+v[8,6,c],v[8,7,c])
            self.assertEqual(sum(v[9,r,c] for r in (3,4,5,6)),v[9,7,c])

    def test_reported_one_dollar_conflict_preserved(self):
        self.assertEqual(self.values[9,5,1]-self.values[8,7,1],Decimal(1))
        self.assertIn('TABLE8_TABLE9_DISTRIBUTABLE_INCOME_DIFFERENCE_PRESERVED',self.output['holds'])

    def test_excess_cost_recovery_both_scopes(self):
        v=self.values
        for c in (1,2):
            self.assertEqual(v[10,3,c]+v[10,4,c],v[10,5,c])
            self.assertEqual(v[10,5,c]+v[10,6,c],v[10,7,c])

    def test_periods_scopes_and_nonacceptance(self):
        self.assertEqual(self.output['accounting_basis'],'MODIFIED_CASH_NON_GAAP_ROYALTY_TRUST')
        self.assertFalse(self.output['production_integrated'])
        self.assertFalse(self.output['family_accepted'])
        for f in self.facts:
            self.assertFalse(f['canonical_qualified'])
            self.assertEqual(f['scale'],0)
            self.assertEqual(f['source_body_sha256'],SOURCE_SHA256)
            if f['table_ordinal']==13:
                self.assertIn(f['property_scope'],('WADDELL_RANCH','TEXAS_ROYALTY'))
                self.assertEqual(f['period_end'],'2026-03-31' if f['column_ordinal']<=2 else '2025-03-31')
            if f['table_ordinal']==10:
                self.assertIn(f['property_scope'],('UNDERLYING_PROPERTIES','NET_TO_TRUST'))

    def test_opening_closing_balances_are_not_duration_flows(self):
        for f in self.facts:
            if f['table_ordinal'] != 9:
                continue
            year=2026 if f['column_ordinal']==1 else 2025
            if f['row_ordinal'] in (3,7):
                self.assertEqual(f['period_kind'],'INSTANT')
                self.assertIsNone(f['period_start'])
                self.assertEqual(f['period_end'],f'{year}-01-01' if f['row_ordinal']==3 else f'{year}-03-31')
                self.assertEqual(f['period_date_basis'],'DERIVED_REPORTED_QUARTER_BOUNDARY')
                self.assertEqual(f['period_boundary'],'OPENING_OF_REPORTED_QUARTER' if f['row_ordinal']==3 else 'CLOSING_OF_REPORTED_QUARTER')
            else:
                self.assertEqual(f['period_kind'],'DURATION')
                self.assertEqual(f['period_start'],f'{year}-01-01')
                self.assertEqual(f['period_end'],f'{year}-03-31')

    def test_changed_source_rejected(self):
        for altered in (self.body+' ',self.body.replace('3,026,801','3,026,802',1),self.body.replace('March 31, 2026','March 31, 2025',1)):
            with self.assertRaisesRegex(ValueError,'EXACT_SOURCE_PIN_REQUIRED'):
                extract(altered)

    def test_numeric_lexemes(self):
        self.assertEqual(number('(1,234',')'),('-1234','NUMERIC'))
        self.assertEqual(number('0.06'),('0.06','NUMERIC'))
        self.assertEqual(number('75','%',True),('75','NUMERIC'))
        for dash in ('—','–','-'):
            self.assertEqual(number(dash),(None,'NULL_DASH'))

    def test_ambiguous_numeric_rejected(self):
        for token,suffix,percent in [('1,23','',False),('1.2.3','',False),('1e3','',False),('NaN','',False),('','',False),('(2','',False),('2',')',False),('-2','',False),('2','x',False),('75','',True),('—','%',True),('$1','',False)]:
            with self.subTest(token=token,suffix=suffix):
                with self.assertRaises(ValueError):number(token,suffix,percent)

    def test_structural_boundaries_rejected(self):
        for source in ('<table><table></table></table>','<table><tr><td>1</tr></table>','<table><tr><td>1'):
            with self.assertRaises(ValueError):Tables(source)

if __name__=='__main__':unittest.main(verbosity=2)
